def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    c_opp = 0
    for i in range(n):
        if opp_at(i) == 'C':
            c_opp += 1
    d_opp = n - c_opp

    if d_opp == 0:
        return 'C'
    if c_opp == 0:
        return 'D'

    last = opp_at(n - 1)

    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    coop_rate = c_opp / n
    remaining = 100 - n

    if coop_rate == 1.0:
        if remaining <= 2:
            return 'D'
        return 'C'

    if remaining <= 4:
        if coop_rate >= 0.65 and streak_d == 0:
            return 'D'
        if streak_d >= 1:
            return 'D'
        if coop_rate >= 0.8:
            return 'D'
        return 'C'

    if streak_d >= 2:
        return 'D'

    if streak_d == 1:
        if coop_rate > 0.75 and streak_c >= 3:
            return 'C'
        if n >= 4 and opp_at(n - 3) == 'C' and opp_at(n - 4) == 'C':
            return 'C'
        return 'D'

    if coop_rate >= 0.85:
        return 'C'

    if n >= 8:
        mirror_score = 0
        total = n - 1
        for i in range(1, n):
            if opp_at(i) == me_at(i - 1):
                mirror_score += 1
        if mirror_score * 10 >= total * 7:
            if coop_rate >= 0.5:
                return me_at(n - 1)
            return 'D'

    if n >= 8:
        alt_score = 0
        for i in range(1, n):
            if opp_at(i) != opp_at(i - 1):
                alt_score += 1
        if alt_score * 10 >= (n - 1) * 9:
            if last == 'C':
                return 'D'
            return 'C'

    if n >= 6:
        same_recent = 0
        for i in range(n - 5, n):
            if history[i][0] == history[i][1]:
                same_recent += 1
        if same_recent >= 4:
            return 'C' if last == 'C' else 'D'

    if last == 'C':
        if coop_rate > 0.6:
            return 'C'
        return 'C'
    else:
        if coop_rate > 0.7 and streak_d <= 1:
            return 'C'
        if coop_rate > 0.55 and rng.random() < 0.25:
            return 'C'
        return 'D'
